const entries = $input.all();

const flagged = entries.filter(e => e.json.certificationStatus === 'FLAGGED');
const violations = entries.filter(e => e.json.certificationStatus === 'REQUIRES_REVIEW');
const clean = entries.filter(e => e.json.certificationStatus === 'CLEAN');

const report = {
  reportId: `CERT-${Date.now()}`,
  generatedAt: new Date().toISOString(),
  period: 'Weekly Access Certification',
  realm: 'TechCorp',
  summary: {
    totalUsers: entries.length,
    flagged: flagged.length,
    sodViolations: violations.length,
    clean: clean.length
  },
  flaggedUsers: flagged.map(e => ({
    username: e.json.username,
    roles: e.json.roles,
    reason: 'High privilege role — requires manager certification'
  })),
  sodViolations: violations.map(e => ({
    username: e.json.username,
    roles: e.json.roles,
    violatingRoles: e.json.violatingRoles,
    reason: 'SoD violation — immediate revocation recommended'
  })),
  recommendation: violations.length > 0
    ? 'IMMEDIATE ACTION REQUIRED — SoD violations detected'
    : 'Review flagged users with their managers'
};

return [{ json: report }];

const users = $('Get-All-Users').all();
const roleItems = $('Get-Roles').all();

// High privilege roles to flag
const highPrivilegeRoles = ['admin', 'manager', 'security-analyst'];

// SoD rules
const sodRules = {
  "manager": "security-analyst",
  "security-analyst": "manager"
};

// Build user role map
const userRoleMap = {};

for (const user of users) {
  const userId = user.json.id;
  const username = user.json.username;
  userRoleMap[userId] = {
    username,
    userId,
    roles: []
  };
}

for (const roleItem of roleItems) {
  const userId = roleItem.pairedItem?.item !== undefined 
    ? users[roleItem.pairedItem.item]?.json.id 
    : null;

  if (userId && userRoleMap[userId]) {
    userRoleMap[userId].roles.push(roleItem.json.name);
  }
}

// Analyze each user
const certificationReport = [];

for (const userId in userRoleMap) {
  const userData = userRoleMap[userId];
  const roles = userData.roles;

  const hasHighPrivilege = roles.some(r => highPrivilegeRoles.includes(r));

  // Check SoD violations
  let sodViolation = false;
  let violatingRoles = [];
  for (const role of roles) {
    if (sodRules[role] && roles.includes(sodRules[role])) {
      sodViolation = true;
      violatingRoles = [role, sodRules[role]];
    }
  }

  certificationReport.push({
    username: userData.username,
    userId: userData.userId,
    roles: roles,
    hasHighPrivilege,
    sodViolation,
    violatingRoles,
    certificationStatus: sodViolation ? 'REQUIRES_REVIEW' : hasHighPrivilege ? 'FLAGGED' : 'CLEAN',
    timestamp: new Date().toISOString()
  });
}

return certificationReport.map(entry => ({ json: entry }));

const report = $input.first().json;

return [{
  json: {
    timestamp: new Date().toISOString(),
    action: 'CERTIFICATION_CAMPAIGN_COMPLETED',
    reportId: report.reportId,
    totalUsers: report.summary.totalUsers,
    flagged: report.summary.flagged,
    sodViolations: report.summary.sodViolations,
    status: report.summary.sodViolations > 0 ? 'ACTION_REQUIRED' : 'REVIEW_REQUIRED',
    recommendation: report.recommendation
  }
}];
